export const OXFORD_3000 = oxford3000Data;

// Level-Specific Subsets for granular loading and filtering
export const OXFORD_A1 = oxford3000Data.filter((w) => w.cefr === 'A1');
export const OXFORD_A2 = oxford3000Data.filter((w) => w.cefr === 'A2');
export const OXFORD_B1 = oxford3000Data.filter((w) => w.cefr === 'B1');
export const OXFORD_B2 = oxford3000Data.filter((w) => w.cefr === 'B2');

export const getCefrLevels = () => ['A1', 'A2', 'B1', 'B2'];
export const getPosOptions = () => ['noun', 'verb', 'adjective', 'adverb', 'preposition', 'conjunction', 'pronoun'];

export const getLexiconByLevel = (level = 'ALL') => {
  if (!level || level === 'ALL') return oxford3000Data;
  switch (level.toUpperCase()) {
    case 'A1': return OXFORD_A1;
    case 'A2': return OXFORD_A2;
    case 'B1': return OXFORD_B1;
    case 'B2': return OXFORD_B2;
    default: return oxford3000Data.filter((w) => w.cefr === level);
  }
};


export const normalizedOxford3000 = oxford3000Data.map((item) => ({
  ...item,
  level: item.cefr,
  translation: item.arabic,
  phonetic: item.ipa,
}));

// Provide normalized array directly on each oxford3000Data item for seamless compatibility
oxford3000Data.forEach((item) => {
  if (!item.level) item.level = item.cefr;
  if (!item.translation) item.translation = item.arabic;
  if (!item.phonetic) item.phonetic = item.ipa;
});

export default oxford3000Data;
